mapper.select:
SELECT
FROM community_comment c JOIN user u ON u.user_id = c.user_id LEFT JOIN community_comment_like ccl ON ccl.comment_id = c.comment_id AND ccl.user_id = #{userId} WHERE c.post_id = #{postId} AND c.parent_comment_id IS NULL AND ( (c.deleted_at IS NULL AND NOT AND NOT ) OR EXISTS (SELECT 1 FROM community_comment r WHERE r.parent_comment_id = c.comment_id AND r.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM blockeduser bu2 WHERE bu2.blocked_user_id = r.user_id AND bu2.user_id = #{userId}) AND NOT EXISTS (SELECT 1 FROM community_report cr2 WHERE cr2.target_type = 'COMMENT' AND cr2.target_id = r.comment_id AND cr2.reporter_user_id = #{userId})) )
AND c.comment_id > #{lastId}
ORDER BY c.comment_id ASC LIMIT #{size}
